class Feedback{postToParentFromIframe(n){parent.postMessage(n,"*")}submit(){const n=$("#gameForm");if(this.validateContent(n)){let t=new FormData(n[0]);n.find("#submitBtn").prop("disabled",!0);$.ajax({method:"POST",url:"/feedback/Add",data:t,processData:!1,contentType:!1}).done(function(t){t.success?(n.find("#failedMsg").hide(),feedback.showSuccessModal(),n.find("#submitBtn").prop("disabled",!1),feedback.postToParentFromIframe({showSuccess:!0})):(n.find("#failedMsg").show(),n.find("#failedMsgContent").html(t.message),n.find("#submitBtn").prop("disabled",!1))})}}resetForm(){$("#Feedback_Category").val("newgame");$("#descText").val("")}validateContent(n){var t=$("#descText").val();return t===""?(n.find("#failedMsg").show(),n.find("#failedMsgContent").html("(The description can't be empty)"),$("#descText").addClass("error-border"),!1):(n.find("#failedMsg").hide(),$("#descText").removeClass("error-border"),!0)}showSuccessModal(){$("#successModal").modal("show")}closeSuccessModal(){feedback.resetForm();feedback.postToParentFromIframe({closeSuccess:!0})}openSelectFile(){$(".to-add-input").trigger("click")}onFileInputChanged(n){var i=n.files[0],t;$(n).parent().parent().find(".to-add-name").html(i.name);$(n).removeClass("to-add-input");$(n).parent().parent().removeAttr("hidden");$('<li class="added-image" hidden><div><img class="attach-img"/><img class="remove-img" onclick="feedback.removeAttachment(this)"/><br/><span class="to-add-name"><\/span><input type="file" accept="image/x-png,image/gif,image/jpeg" class="to-add-input" name="Feedback.Files" hidden onchange="feedback.onFileInputChanged(this)"><\/div><\/li>').insertBefore(".to-add-image");t=$(".image-container ul");t.animate({scrollLeft:t[0].scrollWidth});feedback.updateAttachmentCount()}onDescKeyUp(){console.log("upp");feedback.validateContent($("#gameForm"))}removeAttachment(n){$(n).parent().parent().remove();feedback.updateAttachmentCount()}updateAttachmentCount(){$(".attachment-count").html($(".added-image").length-1)}registerEventHandlers(){$("#successModal").on("hidden.bs.modal",function(){feedback.closeSuccessModal()})}}var feedback=new Feedback;feedback.registerEventHandlers();